65,502,'Jueves','11:00:00','17:00:00','-1','-1','-1','-1'),(866,502,'Viernes','11:00:00','17:00:00','-1','-1','-1','-1'),(867,502,'Sábado','11:00:00','17:00:00','-1','-1','-1','-1'),(868,502,'Domingo','00:00:00','00:00:00','-1','-1','-1','-1');
